import assert from 'node:assert/strict';
import fs from 'node:fs/promises';

export async function runMotionStageSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));let revision=0;
 async function ready(count=3){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelectorAll('.nw-stage-card').length===count&&d.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&d.querySelector('[data-motion-canvas]')&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{timeout:15000},count);}
 async function change(selector,value,count=3){const mark='stage-'+(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.stageOld=mark;if(n.type==='checkbox')n.checked=value;else n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.stageOld!==mark&&d.querySelector('.nw-stage-card');},{timeout:10000},mark);await ready(count);}
 async function pose(progress,selector='.nw-motion-dialog iframe',gid){return page.$eval(selector,(f,{progress,gid})=>{const d=f.contentDocument,id=gid||d.querySelector('.sc').dataset.id;f.contentWindow.__NAG_SCROLL_DIRECTOR[id].set(progress);return Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,src:n.querySelector('img').getAttribute('src'),phase:n.dataset.nwStreamPhase,surface:n.__nwMotionSurface,alpha:+n.querySelector('canvas').style.opacity,left:n.style.left,top:n.style.top,width:n.style.width,height:n.style.height}));},{progress,gid});}
 async function actualScroll(selector,gid){await page.$eval(selector,f=>f.contentWindow.scrollTo(0,f.contentDocument.querySelector('.sc').offsetHeight/2-f.contentWindow.innerHeight/2));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()>.4,{},{selector,gid});const middle=await page.$eval(selector,(f,gid)=>({p:f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress(),phase:+f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase}),gid);assert.ok(Math.abs(middle.phase-(middle.p*100-20)/60*3)<.001);await page.$eval(selector,f=>f.contentWindow.scrollTo(0,0));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()<.05,{},{selector,gid});assert.equal(await page.$eval(selector,f=>f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase),'0.000000');}
 async function exported(gid){await page.evaluate(()=>{document.querySelector('#stage-export')?.remove();const f=document.createElement('iframe');f.id='stage-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#stage-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&document.querySelector('#stage-export').contentDocument.querySelector('.nw-stage-card'),{},gid);}
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,bg:'#527467',elements:[mkEl('label',{text:'Exterior',name:'Exterior'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0]}));
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="center-stage"]');await ready();assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'7');assert.equal(await page.$eval('[data-motion-stream-count]',n=>[n.min,n.max].join(',')),'2,6');assert.equal(await page.$eval('[data-motion-stream="travel"]',n=>n.value),'60');assert.equal(await page.$eval('[data-motion-stream="backgroundType"]',n=>n.value),'none');assert.equal(await page.$('[data-motion-stream="cardRatio"]'),null);
  const start=await pose(0),end=await pose(1);assert.deepEqual(start.map(({phase,...n})=>n),end.map(({phase,...n})=>n));for(let i=0;i<3;i++){const cards=await pose((i+.5)/3);assert.deepEqual(cards.filter(n=>n.alpha>0).map(n=>n.id),[start[i].id]);assert.equal(cards[i].alpha,1);}const entry=(await pose(.1/3))[0],held=(await pose(.5/3))[0],exit=(await pose(.88/3))[0],cx=n=>(n.surface[0].x+n.surface[1].x)/2;assert.ok(cx(entry)>cx(held)&&cx(exit)<cx(held));assert.ok(entry.alpha<1&&exit.alpha<1);async function pixels(){return page.$eval('.nw-motion-dialog iframe',f=>{const n=Array.from(f.contentDocument.querySelectorAll('.nw-stage-card')).find(n=>+n.style.opacity>0),data=n.getContext('2d').getImageData(0,0,n.width,n.height).data;let count=0;for(let i=3;i<data.length;i+=4)if(data[i])count++;return count;});}const withTrails=await pixels();await change('[data-motion-stream="ghosts"]',false);await pose(.88/3);assert.ok(await pixels()<withTrails,'Disabling the trail removes the lagged image copies');await change('[data-motion-stream="ghosts"]',true);await pose(.5);await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/center-stage-desktop.png'});
  await change('[data-motion-stream-count]','2',2);await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true);await change('[data-motion-stream-count]','3');assert.deepEqual((await pose(0)).map(n=>[n.id,n.src]),start.map(n=>[n.id,n.src]));await change('[data-motion-stream-count]','6',6);await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-duplicate]',n=>n.disabled),true);await change('[data-motion-stream-count]','3');await change('[data-motion-stream="cardSize"]','100');await change('[data-motion-stream="travel"]','85');assert.notDeepEqual(await pose(.15),start);await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="turns"]','3');await change('[data-motion-stream="start"]','20');await change('[data-motion-stream="end"]','80');await change('[data-motion-stream="scrollLength"]','420');assert.equal((await pose(.1))[0].phase,'0.000000');assert.equal((await pose(.5))[0].phase,'1.500000');assert.equal((await pose(.9))[0].phase,'3.000000');assert.deepEqual((await pose(.1)).map(({phase,...n})=>n),(await pose(.9)).map(({phase,...n})=>n));assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',n=>n.value='Mi secuencia');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.stream.kind,'center-stage');assert.equal(saved.config.stream.travel,85);assert.equal(saved.assets.length,3);await page.click('[data-motion-saved="'+saved.id+'"]');await ready();const copied=await pose(.35);assert.ok(copied.every(n=>!start.some(o=>o.id===n.id)));assert.deepEqual(copied.map(n=>n.src),start.map(n=>n.src));await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,project:JSON.stringify(project),group:g,outside:sec().elements[0],length:sec().sdLength,enabled:sec().sdEnabled};});assert.equal(inserted.enabled,true);assert.equal(inserted.length,420);assert.equal(inserted.group.bg,'transparent');assert.deepEqual(inserted.outside,before.outside);await page.waitForFunction(id=>document.querySelector('#preview')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id]&&document.querySelector('#preview').contentDocument.querySelector('.nw-stage-card'),{},inserted.gid);await actualScroll('#preview',inserted.gid);await exported(inserted.gid);assert.deepEqual((await pose(.35,'#stage-export',inserted.gid)).map(n=>n.src),copied.map(n=>n.src));await page.$eval('#stage-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].live(),inserted.gid);await actualScroll('#stage-export',inserted.gid);await page.evaluate(()=>document.querySelector('#stage-export').remove());
  await page.evaluate(id=>{NAGWEB_SCROLL_DIRECTOR.scrub(id,.25);NAGWEB_MOTION_LAB.edit(id);},inserted.gid);await ready();await change('[data-motion-stream="travel"]','90');await page.$eval('#preview',f=>f.contentDocument.body.dataset.stageSaved='old');await page.click('[data-motion-save]');await page.waitForFunction(id=>{const f=document.querySelector('#preview');return f?.contentDocument?.body&&!f.contentDocument.body.dataset.stageSaved&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[id]&&f.contentDocument.querySelector('.nw-stage-card');},{},inserted.gid);await actualScroll('#preview',inserted.gid);const scroll=await page.evaluate(()=>JSON.stringify(project));
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();assert.equal(await page.$eval('[data-motion-stream="travel"]',n=>n.value),'90');await change('[data-motion-config="source"]','time');await change('[data-motion-config="duration"]','2');await page.click('[data-motion-save]');const loop=await page.evaluate(()=>JSON.stringify(project));assert.equal(await page.evaluate(()=>sec().sdEnabled),false);await exported(inserted.gid);const clock=await page.$eval('#stage-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].progress(),inserted.gid);await page.waitForFunction(({gid,clock})=>document.querySelector('#stage-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()!==clock,{timeout:3000},{gid:inserted.gid,clock});assert.equal(await page.$eval('#stage-export',f=>!!f.contentDocument.querySelector('.nw-sd-active')),false);await page.evaluate(()=>document.querySelector('#stage-export').remove());await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),scroll);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);assert.equal(await page.evaluate(id=>migrate(JSON.parse(JSON.stringify(project))).pages[0].sections[0].elements.find(e=>e.id===id).nwMotionInstance.stream.kind,inserted.gid),'center-stage');
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="center-stage"]');await ready();await change('[data-motion-stream="frameRatio"]','auto');await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/center-stage-mobile.png'});await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);assert.deepEqual(await pose(.1),await pose(.9));await page.emulateMediaFeatures([]);await page.click('[data-motion-close]');await page.setViewport(viewport);assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="center-stage"]');await ready();await page.click('[data-motion-insert]');const newScene=await page.evaluate(()=>({gid:sec().nwMotionSceneGroup,config:sec().elements.find(e=>e.nwMotionInstance).nwMotionInstance}));assert.equal(newScene.config.template,'center-stage');assert.ok(newScene.gid);await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),newScene.gid);await ready();await page.click('[data-motion-close]');
  console.log('Center Stage: imágenes en orden, entrada/permanencia/salida y estela visible opcional, cantidad 2–6 y recuperación, controles/borrador/Biblioteca, scroll real tras guardar, loop independiente, transparencia, historial/JSON/exportación, escena reeditable, móvil y movimiento reducido OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/center-stage-failure.png'}).catch(()=>{});throw error;}finally{await page.emulateMediaFeatures([]);await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#stage-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}
